if ( ! defined( 'ABSPATH' ) ) { exit; } final class Design_Core_Elementor_Widget_Selection_Engine_V3 { const VERSION = 3; public function select( $component_type, array $requirements = array() ) { $type = sanitize_key( (string) $component_type ); $contract = Design_Core_Elementor_Component_Ontology::get( $type ); if ( ! $contract ) { return new WP_Error( 'design_core_component_type_unknown', 'Unknown component type.' ); } $usage = $this->usage( $requirements['site_widget_usage'] ?? array() ); $input = array_merge( $requirements, array( 'component_type'=>$type, 'limit'=>max( 5, min( 20, (int) ( $requirements['limit'] ?? 10 ) ) ) ) ); $plan = ( new Design_Core_Elementor_Component_Planner() )->plan( $input ); if ( is_wp_error( $plan ) ) { return $plan; } $candidates = array(); foreach ( (array) ( $plan['direct_candidates'] ?? array() ) as $candidate ) { $name = sanitize_key( (string) ( $candidate['name'] ?? '' ) ); $fit = (array) ( $candidate['fit'] ?? array() ); if ( ! $name || 'compatible' !== ( $fit['status'] ?? '' ) || ! empty( $fit['unverified_behaviors'] ) ) { continue; } $site_count = (int) ( $usage[ $name ] ?? 0 ); $bonus = min( .08, log( 1 + max( 0, $site_count ), 10 ) * .04 ); $preferred = in_array( $name, array_map( 'sanitize_key', (array) ( $contract['preferred_widgets'] ?? array() ) ), true ); $score = min( 1, (float) ( $fit['score'] ?? 0 ) + $bonus + ( $preferred ? .04 : 0 ) ); $candidates[] = array_merge( $candidate, array( 'site_usage_count'=>$site_count, 'selection_score'=>round($score,4), 'preferred'=>$preferred ) ); } usort( $candidates, static function ( $a, $b ) { $sa=(float)$a['selection_score'];$sb=(float)$b['selection_score'];return $sa===$sb?strcmp((string)$a['name'],(string)$b['name']):($sa>$sb?-1:1); } ); $top = $candidates[0] ?? null; $recommendation = array( 'type'=>'blocked', 'implementation_tier'=>'blocked', 'reason'=>'no-runtime-widget-clears-contract' ); if ( $top ) { $tier = ! empty( $top['preferred'] ) ? 'exact-native' : 'closest-native'; $recommendation = array( 'type'=>'direct_widget', 'implementation_tier'=>$tier, 'widget'=>$top['name'], 'score'=>$top['selection_score'], 'runtime_fit_score'=>(float)($top['fit']['score']??0), 'site_usage_count'=>(int)$top['site_usage_count'], 'reason'=>!empty($top['preferred'])?'preferred-runtime-widget-clears-contract':'closest-runtime-widget-clears-contract' ); } elseif ( ! empty( $contract['native_composition'] ) ) { $recommendation = array( 'type'=>'native_composition', 'implementation_tier'=>'native-composition', 'roles'=>$contract['native_composition'], 'reason'=>'no-direct-widget-clears-contract' ); } elseif ( ! empty( $contract['custom_widget'] ) ) { $recommendation = array( 'type'=>'custom_native_widget', 'implementation_tier'=>'new-custom-widget', 'widget'=>sanitize_key((string)$contract['custom_widget']), 'reason'=>'native-options-exhausted' ); } return array( 'status'=>'ok', 'selector_version'=>self::VERSION, 'component_type'=>$type, 'recommendation'=>$recommendation, 'candidates'=>array_slice($candidates,0,10), 'selection_order'=>array('reuse-existing-component','exact-native-widget','closest-compatible-widget','closest-widget-plus-scoped-css','native-composition','new-custom-widget'), 'rules'=>array('functional-correctness-before-visual-similarity','runtime-schema-is-authority','native-controls-before-css','scoped-css-presentation-only','native-composition-before-custom-widget','site-usage-is-soft-bonus'), 'base_plan_hash'=>(string)($plan['decision_hash']??''), ); } private function usage( $usage ) { $out=array();foreach((array)$usage as $name=>$count){$key=sanitize_key((string)$name);if($key&&is_numeric($count))$out[$key]=max(0,(int)$count);}return $out; } } 